    function getIngredientMeta(ingName) {
      if (ingredientKnowledgeBase[ingName]) return ingredientKnowledgeBase[ingName];
      for (const key in ingredientKnowledgeBase) {
        if (ingName.toLowerCase().includes(key.toLowerCase()) || key.toLowerCase().includes(ingName.toLowerCase())) {
          return ingredientKnowledgeBase[key];
        }
      }
      return null;
    }

